"export default async function CustomerProductPage({ params, searchParams }: { params: { id: string }, searchParams: { [key: string]: string | string[] | undefined } }) {
  const product = await getProduct(params.id);

  if (!product) {
    notFound();
  }

  // Generate JSON-LD Schema
  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Product',
    name: product.name,
    image: product.images?.map((img: string) => img.startsWith('http') ? img : `${apiBase}${img}`) || [],
    description: product.description,
    sku: product.sku || product._id,
    brand: {
      '@type': 'Brand',
      name: product.brand || 'Stationery Junction',
    },
    offers: {
      '@type': 'Offer',
      url: `https://www.stationeryjunction.com/customer/product/${params.id}`,
      priceCurrency: 'INR',
      price: product.price,
      itemCondition: 'https://schema.org/NewCondition',
      availability: product.stock > 0 ? 'https://schema.org/InStock' : 'https://schema.org/OutOfStock',
    },
    ...(product.rating ? {
      aggregateRating: {
        '@type': 'AggregateRating',
        ratingValue: product.rating,
        reviewCount: product.reviews || 1,
      }
    } : {})
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />
      <ProductDetailClient initialProduct={product} searchParams={searchParams} />
    </>
  );
}"

