"import http from 'k6/http';
import { check, sleep, group } from 'k6';

export const options = {
  stages: [
    // Baseline: 10 users for 20s
    { duration: '20s', target: 10 },

    // Sudden Spike to 500 users in 10s
    { duration: '10s', target: 500 },

    // Hold Spike at 500 users for 30s
    { duration: '30s', target: 500 },

    // Drop back down to 10 users in 10s
    { duration: '10s', target: 10 },

    // Recovery evaluation: 10 users for 30s
    { duration: '30s', target: 10 },

    // Cool down to 0 users in 10s
    { duration: '10s', target: 0 },
  ],
  thresholds: {
    http_req_duration: ['p(95)<1500'], // 95% of requests during spike & recovery under 1500ms
    http_req_failed: ['rate<0.05'],     // overall error rate under 5%
  },
};

const BASE_URL = 'http://localhost:8000';

export default function () {
  group('Spike Load - Public Catalog', function () {
    const responses = http.batch([
      ['GET', `${BASE_URL}/api/products/public`],
      ['GET', `${BASE_URL}/api/categories/public`],
      ['GET', `${BASE_URL}/api/brands/public`],
      ['GET', `${BASE_URL}/api/banners/public`]
    ]);

    check(responses[0], { 'products status is 200': (r) => r.status === 200 });
    check(responses[1], { 'categories status is 200': (r) => r.status === 200 });
    check(responses[2], { 'brands status is 200': (r) => r.status === 200 });
    check(responses[3], { 'banners status is 200': (r) => r.status === 200 });
  });

  sleep(1);
}
"

"import http from 'k6/http';
import { check, sleep } from 'k6';
import { randomItem } from 'https://jslib.k6.io/k6-utils/1.2.0/index.js';

// Realistic homepage load test:
// Each VU simulates a single real user browsing the app.
// They hit ONE endpoint per iteration (not 4 simultaneously),
// then pause to "read" before the next action — just like a real browser.
export const options = {
  stages: [
    // Baseline: 1 user
    { duration: '30s', target: 1 },
    { duration: '30s', target: 1 },

    // Ramp to 50
    { duration: '30s', target: 50 },
    { duration: '1m',  target: 50 },

    // Ramp to 500
    { duration: '1m',  target: 500 },
    { duration: '2m',  target: 500 },

    // Cool down
    { duration: '30s', target: 0 },
  ],
  thresholds: {
    // 95% of all requests must complete within 500ms
    http_req_duration: ['p(95)<500'],
    // Error rate must stay below 1%
    http_req_failed: ['rate<0.01'],
  },
};

const BASE_URL = 'http://localhost:8000';

// Public catalog endpoints a real user would hit, one at a time
const ENDPOINTS = [
  { url: `${BASE_URL}/api/products/public`,   label: 'products' },
  { url: `${BASE_URL}/api/categories/public`, label: 'categories' },
  { url: `${BASE_URL}/api/brands/public`,     label: 'brands' },
  { url: `${BASE_URL}/api/banners/public`,    label: 'banners' },
];

export default function () {
  // Each iteration: pick one endpoint (random, as a real user would navigate)
  const endpoint = randomItem(ENDPOINTS);

  const res = http.get(endpoint.url);

  check(res, {
    [`${endpoint.label} status is 200`]: (r) => r.status === 200,
    [`${endpoint.label} response time < 500ms`]: (r) => r.timings.duration < 500,
  });

  // Simulate user think/read time: 1–3 seconds between actions
  sleep(Math.random() * 2 + 1);
}
