@router.put("/{user_id}/grant-seller-access", response_model=UserResponse)
async def grant_seller_access(
    user_id: str,
    permissions: GrantSellerAccessRequest,
    current_user: dict = Depends(require_super_admin),
):
    """Grant seller admin access to a wholesaler user (Super Admin only)."""
    user = await user_repository.findById(user_id)
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    if user.get("role") != "wholesaler":
        raise HTTPException(
            status_code=400,
            detail="Seller admin access can only be granted to wholesaler (business) users.",
        )
    existing_perms = user.get("sellerPermissions") or {}
    update_data = {
        "isSellerAdmin": True,
        "sellerPermissions": {
            "allowDeliverySlots": permissions.allowDeliverySlots,
            "allowUrgentDelivery": permissions.allowUrgentDelivery,
            "serviceablePincodes": existing_perms.get("serviceablePincodes", []),
            "urgentPincodes": existing_perms.get("urgentPincodes", []),
            "slotPincodes": existing_perms.get("slotPincodes", []),
        },
    }
    updated = await user_repository.update(user_id, update_data)
    return UserResponse(**updated)


