def apply_indexes():
    for db_name, url in urls.items():
        print(f"Applying to {db_name}...")
        try:
            engine = create_engine(url)
            with engine.connect() as conn:
                for script in scripts:
                    print(f"  Reading {os.path.basename(script)}")
                    with open(script, 'r') as f:
                        content = f.read()

