    if (!sessionId) return;
    await api.post('/recommendations/events', payload, {
      headers: { 'X-Session-Id': sessionId },
    });
  } catch (err) {
    if (__DEV__) {
      console.warn('Failed to track recommendation event:', err);
    }
  }
};
