def get_db_type() -> str:
    return os.environ.get("DB_TYPE", "oracle").lower()


def get_database_url() -> str | None:
    db_type = get_db_type()
    if db_type == "mysql":
        url = os.environ.get("MYSQL_DATABASE_URL")
        if not url:
            # Fallback to DATABASE_URL if they put the MySQL URL there
            url = os.environ.get("DATABASE_URL")
            if url and "oracle" in url:
                return None
        if not url:
            return None
        if url.startswith("mysql://"):
            url = "mysql+aiomysql://" + url[8:]
        return url
    else:
        url = os.environ.get("DATABASE_URL")
        if not url:
            return None
        if url.startswith("oracle:"):
            url = "oracle+oracledb_async:" + url[6:]
        elif url.startswith("oracle+oracledb:"):
            url = "oracle+oracledb_async:" + url[16:]
        return url


