@router.put("/{user_id}/mark-seller", response_model=UserResponse)
async def mark_user_as_seller(
    user_id: str,
    data: MarkSellerRequest,
    current_user: dict = Depends(require_super_admin),
):
    """Grant or revoke seller admin access for a user (Super Admin only).
    The user can be of any role. isSellerAdmin=True grants seller access, False revokes it.
    """
    user = await user_repository.findById(user_id)
    if not user:
        raise HTTPException(status_code=404, detail="User not found")

    if user.get("role") == "super_admin":
        raise HTTPException(status_code=400, detail="Cannot modify super admin seller status")

    update_payload: Dict[str, Any] = {
        "isSellerAdmin": data.isSellerAdmin,
    }
    if data.sellerPermissions is not None:
        update_payload["sellerPermissions"] = data.sellerPermissions
    if data.commissionOverridePct is not None:
        update_payload["commissionOverridePct"] = data.commissionOverridePct

    # When granting seller access, ensure approval is set
    if data.isSellerAdmin:
        update_payload["approvalStatus"] = "approved"
        update_payload["isActive"] = True

    updated_user = await user_repository.update(user_id, update_payload)
    return UserResponse(**updated_user)"

